<?php
use app\components\widgets\DataSummaryWidget;
use yii\helpers\Html;
$this->title = 'คำขอบุคคลภายนอก';
$this->beginBlock('page-title'); ?><?= Html::encode($this->title) ?><?php $this->endBlock();
$this->beginBlock('page-action'); ?><?= $this->render('../_menu', ['active' => 'guest']) ?><?php $this->endBlock();
?>
<div class="container-fluid py-3"><?php if (Yii::$app->session->hasFlash('success')): ?><div class="alert alert-success"><?= Html::encode(Yii::$app->session->getFlash('success')) ?></div><?php endif; ?><div class="card border-0 shadow-sm"><div class="card-header bg-body"><div class="fw-semibold">รายการรออนุญาต</div></div><div class="card-body p-0"><table class="table table-hover align-middle mb-0"><thead><tr><th>เลขคำขอ</th><th>บุคคลภายนอก</th><th>ช่วงวันที่</th><th>สถานะ</th><th class="text-end">ดำเนินการ</th></tr></thead><tbody><?php foreach ($dataProvider->models as $model): ?><tr><td><?= Html::encode($model->request_no) ?></td><td><strong><?= Html::encode($model->guest_name) ?></strong><div class="small text-body-secondary"><?= Html::encode($model->relationship ?: '—') ?></div></td><td><?= Html::encode($model->start_date . ' ถึง ' . $model->end_date) ?></td><td><?= Html::encode($model->status) ?></td><td class="text-end"><?php if ($model->status === 'pending'): ?><?= Html::a('อนุญาต', ['decide', 'id' => $model->id, 'decision' => 'approved'], ['class' => 'btn btn-sm btn-success', 'data-method' => 'post']) ?> <?= Html::a('ไม่อนุญาต', ['decide', 'id' => $model->id, 'decision' => 'rejected'], ['class' => 'btn btn-sm btn-outline-danger', 'data-method' => 'post']) ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php if (!$dataProvider->totalCount): ?><div class="text-center py-5"><div class="fw-semibold">ไม่มีคำขอ</div></div><?php endif; ?></div><div class="card-footer bg-body"><?= DataSummaryWidget::widget(['dataProvider' => $dataProvider]) ?></div></div></div>
